using System;using System.IO;using System.Collections.Generic;using System.Drawing;using FleetLab;
// Compares the delivered pure weapon/movie pair against separate copied-code
// shared-CRT traces. No forms, native devices or original executable are run.
class CheckWeaponRandomTraces {
 static int Main(string[] args){try{if(args.Length!=2)return 2;var groups=new Dictionary<string,List<string[]>>();foreach(string row in File.ReadAllLines(args[0])){if(row.StartsWith("Seed"))continue;string[] c=row.Split(',');string key=c[0]+","+c[1]+","+c[2];if(!groups.ContainsKey(key))groups.Add(key,new List<string[]>());groups[key].Add(c);}int draws=0;foreach(var item in groups){string[] first=item.Value[0];uint seed=uint.Parse(first[0]),state=seed;int type=int.Parse(first[1]),weapon=-1,movie=-1,count=0;bool opponent=first[2]=="OpponentNativePrefix";bool sawTarget=false,sawStage=false,sawMovie=false;
  foreach(var row in item.Value){string kind=row[4];int value=int.Parse(row[6]);if(kind=="rand"){state=unchecked(state*214013u+2531011u);if(value!=(int)((state>>16)&32767))throw new Exception("Native CRT draw differs "+item.Key);count++;draws++;}if(uint.Parse(row[7])!=state)throw new Exception("Native shared state differs "+item.Key);if(kind=="SelectedWeapon")weapon=value;if(kind=="MovieRequest"){if(sawTarget||sawStage)throw new Exception("Native movie follows target/stage");movie=value;sawMovie=true;}if(kind=="TargetRequestStub"){if(!sawMovie)throw new Exception("Native target precedes firing movie");weapon=value;sawTarget=true;}if(kind=="NextStageStub"){if(!sawTarget)throw new Exception("Stage precedes target");sawStage=true;}}
  if(opponent&&(!sawTarget||!sawStage))throw new Exception("Opponent prefix boundary");var board=new Board();if(!board.Place(new Point(0,0),1,true,"Probe",type))throw new Exception("Fixture ship");var rng=new NativeRandom(seed);var actual=ClassicWeapons.Choose(board.Ships[0],opponent,rng);if(actual.WeaponId!=weapon||actual.MovieId!=movie||actual.RandomCalls!=count||rng.State!=state)throw new Exception("Delivered weapon/movie pair differs from native trace "+item.Key);
 }if(groups.Count!=40||draws!=80)throw new Exception("Probe coverage differs");string report="PASS40bounded probes/80actual native CRT draws; shared state, weapon/movie output and delivered pair agree.\r\n20opponent-prefix probes confirm original weapon/movie-before-target order. Target and next-stage logic remain recording stubs;20player pairs are harness-ordered. Not a complete native turn/session or a runtime stream change.";File.WriteAllText(args[1],report);Console.WriteLine(report);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
